import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useParams } from 'react-router-dom';

export default function ExperiencePage(){
  const { id } = useParams();
  const [exp,setExp] = useState(null);
  const [date,setDate] = useState('');
  useEffect(()=> {
    axios.get(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/experiences/${id}`)
      .then(r=> setExp(r.data))
  },[id]);

  const handleBook = async () => {
    const token = localStorage.getItem('token');
    const res = await axios.post(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/bookings/create-checkout-session`,
      { experienceId: id, date, guests: 1 },
      { headers: { Authorization: `Bearer ${token}` } }
    );
    window.location.href = res.data.url; // redirect to stripe checkout
  };

  if (!exp) return <div>جارِ التحميل...</div>;
  return (
    <div>
      <h2>{exp.title}</h2>
      <img src={exp.media?.[0]} style={{width:400}} />
      <p>{exp.description}</p>
      <p>Price: ${(exp.price/100).toFixed(2)}</p>
      <input type="date" value={date} onChange={e=>setDate(e.target.value)} />
      <button onClick={handleBook}>احجز الآن</button>
    </div>
  )
}
